sys_script_client.script:
function onLoad() {


    if (!g_user.hasRole('x_hsb11_mss_fund_0.FA_Operations_Manager')) {
        if ((g_user.userID != g_form.getValue('assigned_to') && g_form.getValue('assigned_to') != "") || g_form.getValue('state') == '203') {
            var fields = g_form.getEditableFields();
            for (var x = 0; x < fields.length; x++) {
                g_form.setReadOnly(fields[x], true);
            }
        }
    }

    if (g_form.getValue('state') == '203') {
		var fields = g_form.getEditableFields();
        for (var j = 0; j < fields.length; j++) {
            g_form.setReadOnly(fields[j], true);
        }
    }


}
